import json,datetime
from pathlib import Path
root=Path(__file__).resolve().parent.parent
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
d=json.loads((root/'run.json').read_text());d['status']='completed';d['ended_at']=now;d['usage']['wall_time_seconds']=(datetime.datetime.fromisoformat(now)-datetime.datetime.fromisoformat(d['started_at'])).total_seconds()
d['attempts']=[{'attempt':1,'status':'failed','path':'artifacts/attempt-01','failure':'Generator failed on incorrect generic MOSFET symbol library lookup.','log':'logs/attempt-01-generation.log'},{'attempt':2,'status':'completed','path':'artifacts/attempt-02','notes':'Routed candidate; ERC library/grid warnings, DRC silk warnings and schematic parity findings retained.'},{'attempt':3,'status':'completed','path':'artifacts/attempt-03','notes':'Final repaired candidate; ERC, DRC, parity and unconnected checks all zero.'}]
d['artifacts']=[str(p.relative_to(root)) for p in sorted((root/'artifacts').rglob('*')) if p.is_file()];d['failure']=None;(root/'run.json').write_text(json.dumps(d,indent=2)+'\n')
result={'status':'completed','final_attempt':'artifacts/attempt-03','generated_files':d['artifacts'],'validation':{'erc':{'passed':True,'violation_count':0,'log':'logs/attempt-03-erc.json','exit_code':0},'pcb_drc':{'passed':True,'violation_count':0,'unconnected_count':0,'schematic_parity_count':0,'log':'logs/attempt-03-drc.json','exit_code':0},'schematic_netlist_export':{'passed':True,'log':'logs/attempt-03-netlist.log','exit_code':0},'schematic_svg_export':{'passed':True,'log':'logs/attempt-03-sch-svg.log','exit_code':0},'pcb_svg_export':{'passed':True,'log':'logs/attempt-03-pcb-svg.log','exit_code':0},'geometry_connectivity':{'log':'logs/geometry-connectivity-audit.json'},'hardware_testing':None,'simulation':None},'known_limitations':['Native library tables use local absolute paths; another installation may require path changes.','Capacitor procurement part numbers and effective capacitance under DC bias were not assessed.','No hardware tests, thermal measurements, simulation or assembly validation performed.','Grid router creates many short editable track segments.'],'failure':None,'started_at':d['started_at'],'ended_at':now,'wall_time_seconds':d['usage']['wall_time_seconds']}
(root/'result.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps({'status':result['status'],'elapsed_seconds':result['wall_time_seconds'],'final_attempt':result['final_attempt']}))
